-- Archive-capable Amoy observers for the same TEST fund journey.
-- Contract 2AF1E21B2BF1CFB892C557E557E5A4F8AB257A799FA1D89E64B756F9E372B746.
-- Five body-only cutovers; no grant, schema, role, business row or historical evidence change.
do $amoy_archive_observers$
declare
  targets constant jsonb:=$archive_observer_targets$[{"oid":24934,"signature":"bx1_portal.record_funding_observation(uuid,jsonb)","sha":"582cf7ae3a77c986b66ba500c556445af34aa05cb227a83622242d3705785b54","metadata":{"oid":"24934","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"record_funding_observation","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["eid","facts"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"original":"\ndeclare e bx1_portal.funding_verification_expectations; r bx1_portal.funding_routes; f bx1_portal.funding_references; o bx1_portal.funding_obligations;\n  prior bx1_portal.funding_observations; inserted bx1_portal.funding_observations; claimed uuid; c jsonb; old_claims text:=current_setting('request.jwt.claims',true);\n  expected_route jsonb; source jsonb; source_urls text[]; in_policy boolean; result jsonb; amount numeric; observed_block numeric;\nbegin\n  select * into e from bx1_portal.funding_verification_expectations where id=eid;\n  if e.id is null or e.expires_at<=clock_timestamp() or jsonb_typeof(facts) is distinct from 'object' or octet_length(facts::text)>16384 then raise exception 'funding_expectation_expired' using errcode='42501'; end if;\n  -- Only minimal claims captured by the authenticated mint are restored. Never\n  -- copy a service/browser actor from observation payload into authorization.\n  perform set_config('request.jwt.claims',e.trusted_claims::text,true); c:=e.operating_context;\n  if bx1_portal.funding_session() is not true or auth.uid() is distinct from e.actor_id or bx1_portal.valid_operating_context(c) is not true then raise exception 'funding_verifier_actor_expired' using errcode='42501'; end if;\n  if e.kind='ROUTE' then select * into r from bx1_portal.funding_routes where id=e.target_id;\n  else\n    select * into f from bx1_portal.funding_references where id=e.target_id;\n    select * into o from bx1_portal.funding_obligations where id=f.obligation_id;\n    select * into r from bx1_portal.funding_routes where id=o.route_id;\n  end if;\n  if r.id is null then raise exception 'funding_expectation_target_missing' using errcode='42501'; end if;\n  perform bx1_portal.funding_lock(c,r.organisation_id,r.product_id,o.subscription_id,o.id);\n  select * into r from bx1_portal.funding_routes where id=r.id for update;\n  if e.kind='REFERENCE' then select * into f from bx1_portal.funding_references where id=f.id; end if;\n  -- Idempotent replay is allowed only for identical immutable observations,\n  -- after fresh caller and context checks, without re-consuming the receipt.\n  select * into inserted from bx1_portal.funding_observations where expectation_id=e.id;\n  if inserted.id is not null then\n    if inserted.facts is distinct from facts then raise exception 'funding_observation_replay_conflict' using errcode='23505'; end if;\n    result:=jsonb_build_object('observation_id',inserted.id,'status',inserted.status);\n    perform set_config('request.jwt.claims',coalesce(old_claims,''),true); return result;\n  end if;\n  if e.expires_at<=clock_timestamp() or e.version is distinct from (case when e.kind='ROUTE' then r.revision else f.revision end)\n    or not(bx1_portal.funding_actions(c,e.kind,e.target_id)?case when e.kind='ROUTE' then 'verify_funding_route' else 'verify_funding_reference' end) then raise exception 'funding_expectation_stale' using errcode='42501'; end if;\n  expected_route:=e.expected->'route';\n  if expected_route is distinct from jsonb_build_object('id',r.id,'revision',case when e.kind='REFERENCE' then f.claim_route_revision else r.revision end,\n    'environment','TESTNET','chain_id',80002,'token_address',r.token_address,'token_runtime_hash',r.token_runtime_hash,'token_decimals',r.token_decimals,'receiving_address',r.receiving_address)\n    or e.expectation_hash is distinct from encode(sha256(convert_to(e.expected::text,'UTF8')),'hex') then raise exception 'funding_expectation_identity_changed' using errcode='23514'; end if;\n  if e.kind='REFERENCE' and e.expected->'reference' is distinct from jsonb_build_object('id',f.id,'obligation_id',o.id,'investment_account_id',o.investment_account_id,\n    'actor_id',f.actor_id,'payer_address',f.payer_address,'transaction_hash',f.transaction_hash,'log_index',f.log_index,'claim_signature',f.claim_signature,'created_at',f.created_at,'obligation_created_at',o.created_at) then raise exception 'funding_expectation_identity_changed' using errcode='23514'; end if;\n  if facts->'version' is distinct from '1'::jsonb or facts->>'kind' is distinct from e.kind or facts->'chain_id' is distinct from '80002'::jsonb\n    or coalesce(facts->>'status','') not in ('VERIFIED','INVALID') or facts->>'token_address' is distinct from r.token_address\n    or facts->>'token_runtime_hash' is distinct from r.token_runtime_hash or facts->'token_decimals' is distinct from to_jsonb(r.token_decimals)\n    or facts->>'receiving_address' is distinct from r.receiving_address or coalesce(facts->>'block_number','') !~ '^[0-9]{1,78}$'\n    or coalesce(facts->>'block_hash','') !~ '^0x[0-9a-f]{64}$' or facts->>'block_timestamp' is null\n    or jsonb_typeof(facts->'providers') is distinct from 'array' or jsonb_array_length(facts->'providers')<>2 then raise exception 'funding_invalid_observation' using errcode='22023'; end if;\n  observed_block:=(facts->>'block_number')::numeric;\n  if not isfinite((facts->>'block_timestamp')::timestamptz) or (facts->>'block_timestamp')::timestamptz>clock_timestamp()+interval '1 minute' then raise exception 'funding_invalid_block_time' using errcode='22023'; end if;\n  select array_agg(x->>'url' order by x->>'url') into source_urls from jsonb_array_elements(facts->'providers') x;\n  if source_urls is distinct from array['https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.drpc.org']::text[] then raise exception 'funding_invalid_sources' using errcode='22023'; end if;\n  for source in select value from jsonb_array_elements(facts->'providers') loop\n    if coalesce(source->>'finalized_block_number','') !~ '^[0-9]{1,78}$' or coalesce(source->>'finalized_block_hash','') !~ '^0x[0-9a-f]{64}$'\n      or (source->>'finalized_block_number')::numeric<observed_block then raise exception 'funding_not_finalized' using errcode='22023'; end if;\n  end loop;\n  if e.kind='ROUTE' then\n    if facts->>'status' is distinct from 'VERIFIED' then raise exception 'funding_invalid_route_observation' using errcode='22023'; end if;\n  else\n    if facts->>'transaction_hash' is distinct from f.transaction_hash or facts->'log_index' is distinct from to_jsonb(f.log_index)\n      or facts->>'payer_address' is distinct from f.payer_address or coalesce(facts->>'transaction_index','') !~ '^[0-9]{1,10}$'\n      or coalesce(facts->>'claim_hash','') !~ '^0x[0-9a-f]{64}$' then raise exception 'funding_receipt_mismatch' using errcode='22023'; end if;\n    prior:=bx1_portal.funding_last_observation(f.id);\n    if facts->>'status'='INVALID' then\n      if facts->>'reason_code' is distinct from 'RECEIPT_REVERTED' or facts?'amount_base_units' or exists(select 1 from bx1_portal.funding_receipt_claims where reference_id=f.id) then raise exception 'funding_not_conclusively_unpaid' using errcode='23514'; end if;\n    else\n      if coalesce(facts->>'amount_base_units','') !~ '^[1-9][0-9]{0,77}$' then raise exception 'funding_invalid_amount' using errcode='22023'; end if;\n      amount:=(facts->>'amount_base_units')::numeric;\n      if amount>=power(2::numeric,256) then raise exception 'funding_amount_overflow' using errcode='22023'; end if;\n      if prior.status='VERIFIED' and (prior.amount_base_units is distinct from amount or prior.block_hash is distinct from facts->>'block_hash') then raise exception 'funding_verified_fact_conflict' using errcode='23514'; end if;\n    end if;\n  end if;\n  insert into bx1_portal.funding_observations(expectation_id,route_id,reference_id,status,facts,amount_base_units,block_number,block_hash)\n    values(e.id,r.id,f.id,facts->>'status',facts,amount,observed_block,facts->>'block_hash') returning * into inserted;\n  if e.kind='REFERENCE' then\n    if facts->>'status'='VERIFIED' then\n      insert into bx1_portal.funding_receipt_claims(chain_id,transaction_hash,log_index,reference_id,first_observation_id)\n        values(80002,f.transaction_hash,f.log_index,f.id,inserted.id) on conflict(chain_id,transaction_hash,log_index) do nothing;\n      select reference_id into claimed from bx1_portal.funding_receipt_claims where chain_id=80002 and transaction_hash=f.transaction_hash and log_index=f.log_index;\n      if claimed is distinct from f.id then raise exception 'funding_receipt_already_claimed' using errcode='23505'; end if;\n      in_policy:=bx1_portal.funding_route_current(r.id) and bx1_portal.funding_account_current(o.id)\n        and (facts->>'block_timestamp')::timestamptz>o.created_at and facts->>'policy_status' is distinct from 'UNAPPLIED'\n        and not exists(select 1 from bx1_portal.subscriptions where id=o.subscription_id and status='CANCELLED');\n      update bx1_portal.funding_references set revision=revision+1,status=case when status='POSTED' then 'POSTED' when status='UNAPPLIED' or in_policy is not true then 'UNAPPLIED' else 'VERIFIED' end where id=f.id;\n    else\n      update bx1_portal.funding_references set revision=revision+1,status=case when status in ('UNAPPLIED','REJECTED_UNPAID') then status else 'SUBMITTED' end where id=f.id;\n    end if;\n    update bx1_portal.funding_obligations set revision=revision+1 where id=o.id;\n  end if;\n  insert into bx1_portal.events(subject_id,organisation_id,investor_id,kind,actor_id,summary)\n    values(coalesce(f.id,r.id),r.organisation_id,o.investor_id,'funding_observation',e.actor_id,'Server-verified finalized TESTNET evidence recorded; no production money or issued holding.');\n  if e.expires_at<=clock_timestamp() or bx1_portal.funding_session() is not true or bx1_portal.valid_operating_context(c) is not true\n    or not(bx1_portal.funding_actions(c,e.kind,e.target_id)?case when e.kind='ROUTE' then 'verify_funding_route' else 'verify_funding_reference' end) then raise exception 'funding_observation_authority_expired' using errcode='42501'; end if;\n  result:=jsonb_build_object('observation_id',inserted.id,'status',inserted.status);\n  perform set_config('request.jwt.claims',coalesce(old_claims,''),true); return result;\nexception when others then\n  perform set_config('request.jwt.claims',coalesce(old_claims,''),true); raise;\nend ","cuts":[{"name":"funding_pair","from":"source_urls is distinct from array['https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.drpc.org']::text[]","to":"(source_urls is distinct from array['https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.drpc.org']::text[]\n    and source_urls is distinct from array['https://polygon-amoy.drpc.org','https://polygon-amoy.gateway.tenderly.co']::text[])","count":1}]},{"oid":33625,"signature":"bx1_portal.fund_setup_observers_valid(jsonb)","sha":"bfc4c603e62cc227707a115cb04943d69564cd3cf6a5e324f3c2f6ea347374b2","metadata":{"oid":"33625","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"fund_setup_observers_valid","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["result"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"original":"\ndeclare entry jsonb;urls text[]:='{}';\nbegin\n  if pg_catalog.jsonb_typeof(result->'providers') is distinct from 'array' or pg_catalog.jsonb_array_length(result->'providers')<>2 then return false;end if;\n  for entry in select value from pg_catalog.jsonb_array_elements(result->'providers') loop\n    if pg_catalog.jsonb_typeof(entry) is distinct from 'object' or entry-array['url','finalized_block_number','finalized_block_hash']<>'{}'\n      or not(entry ?& array['url','finalized_block_number','finalized_block_hash'])\n      or pg_catalog.jsonb_typeof(entry->'url') is distinct from 'string'\n      or entry->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com')\n      or pg_catalog.jsonb_typeof(entry->'finalized_block_number') is distinct from 'string'\n      or entry->>'finalized_block_number' !~ '^[1-9][0-9]{0,77}$'\n      or pg_catalog.jsonb_typeof(entry->'finalized_block_hash') is distinct from 'string'\n      or entry->>'finalized_block_hash' !~ '^0x[0-9a-f]{64}$' then return false;end if;\n    urls:=pg_catalog.array_append(urls,entry->>'url');\n    if result->>'block_number' is not null and (result->>'block_number' !~ '^[1-9][0-9]{0,77}$'\n      or (entry->>'finalized_block_number')::numeric<(result->>'block_number')::numeric) then return false;end if;\n  end loop;\n  return urls[1]<>urls[2];\nexception when others then return false;\nend ","cuts":[{"name":"setup_member","from":"entry->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com')","to":"entry->>'url' not in ('https://polygon-amoy.drpc.org','https://polygon-amoy-bor-rpc.publicnode.com','https://polygon-amoy.gateway.tenderly.co')","count":1},{"name":"setup_pair","from":"return urls[1]<>urls[2];","to":"return urls[1]<>urls[2] and ('https://polygon-amoy.drpc.org'=any(urls)) is true;","count":1}]},{"oid":36424,"signature":"bx1_portal.record_fund_admission(uuid,jsonb,text)","sha":"41bd2d85e87751e1539184232ea14a9888426bf3617ba64ccf3749c0afc1df9a","metadata":{"oid":"36424","proacl":["postgres=X/postgres","bx1_fund_execution_worker=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"record_fund_admission","prorows":0,"pronargs":3,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["request_id","candidate","admitted_manifest_hash"],"proargtypes":["2950","3802","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"original":"\ndeclare prior text;r bx1_portal.fund_admission_requests;s bx1_portal.fund_setups;p bx1_private.roleplay_policies;\n  manifest jsonb;proof_refs jsonb;receipt_kind text;receipt_id uuid;evidence jsonb;capacity record;slot record;expiry timestamptz;policy_hash text;provider jsonb;\nbegin\n  prior:=bx1_portal.fund_admission_worker_enter(request_id);\n  select * into r from bx1_portal.fund_admission_requests where id=request_id for update;\n  if r.status='ADMITTED' then\n    if r.result_hash is distinct from bx1_portal.fund_digest(candidate) then raise exception 'fund_admission_result_conflict' using errcode='23505';end if;\n    perform set_config('request.jwt.claims',prior,true);return jsonb_build_object('request_id',r.id,'status',r.status,'manifest_id',r.manifest_id,'signer_policy_id',r.signer_policy_id);\n  end if;\n  select * into s from bx1_portal.fund_setups where id=r.setup_id for share;\n  select * into p from bx1_private.roleplay_policies where id=r.roleplay_policy_id for share;\n  manifest:=candidate->'manifest';proof_refs:=r.input->'proof_refs';expiry:=least(s.expires_at,p.valid_until,\n    (select valid_until from bx1_portal.fund_contract_release_receipts where id=r.conformance_receipt_id));\n  -- Missing/JSON-null observations must fail before casts or nullable SQL time\n  -- comparisons. They cannot be upgraded to a governance/network receipt.\n  if jsonb_typeof(candidate->'observed') is distinct from 'object'\n    or jsonb_typeof(candidate#>'{observed,block}') is distinct from 'object'\n    or jsonb_typeof(candidate#>'{observed,providers}') is distinct from 'array'\n    or jsonb_typeof(candidate#>'{observed,block,number}') is distinct from 'string'\n    or coalesce(candidate#>>'{observed,block,number}','') !~ '^(0|[1-9][0-9]{0,12})$'\n    or jsonb_typeof(candidate#>'{observed,block,hash}') is distinct from 'string'\n    or coalesce(candidate#>>'{observed,block,hash}','') !~ '^0x[0-9a-f]{64}$'\n    or candidate#>>'{observed,block,hash}'='0x'||repeat('0',64)\n    or jsonb_typeof(candidate#>'{observed,block,timestamp}') is distinct from 'string'\n    or coalesce(candidate#>>'{observed,block,timestamp}','')='' then\n    raise exception 'fund_admission_complete_observation_required' using errcode='23514';end if;\n  perform bx1_portal.require_keys(candidate#>'{observed,block}',array['number','hash','timestamp']);\n  if not pg_catalog.isfinite((candidate#>>'{observed,block,timestamp}')::timestamptz) then\n    raise exception 'fund_admission_finite_observation_required' using errcode='23514';end if;\n  for provider in select value from jsonb_array_elements(candidate#>'{observed,providers}') loop\n    if jsonb_typeof(provider) is distinct from 'object'\n      or jsonb_typeof(provider->'url') is distinct from 'string'\n      or jsonb_typeof(provider->'finalized_block_number') is distinct from 'string'\n      or coalesce(provider->>'finalized_block_number','') !~ '^(0|[1-9][0-9]{0,12})$'\n      or jsonb_typeof(provider->'finalized_block_hash') is distinct from 'string'\n      or coalesce(provider->>'finalized_block_hash','') !~ '^0x[0-9a-f]{64}$'\n      or provider->>'finalized_block_hash'='0x'||repeat('0',64) then\n      raise exception 'fund_admission_complete_provider_observation_required' using errcode='23514';end if;\n    perform bx1_portal.require_keys(provider,array['url','finalized_block_number','finalized_block_hash']);\n    if (provider->>'finalized_block_number')::numeric<(candidate#>>'{observed,block,number}')::numeric then\n      raise exception 'fund_admission_observation_not_finalized' using errcode='23514';end if;\n  end loop;\n  if jsonb_typeof(candidate) is distinct from 'object' or candidate->>'status' is distinct from 'NOT_ADMITTED'\n    or candidate->>'environment' is distinct from 'TESTNET' or candidate->>'chain_id' is distinct from '80002'\n    or candidate->>'setup_id' is distinct from s.id::text or candidate->>'setup_revision' is distinct from s.revision::text\n    or candidate->>'product_id' is distinct from s.product_id::text or candidate->>'offering_revision_id' is distinct from s.offering_revision_id::text\n    or candidate->>'terms_hash' is distinct from s.terms_hash or candidate->>'configuration_hash' is distinct from s.configuration_hash\n    or candidate->>'product_binding_hash' is distinct from r.input->>'product_binding_hash'\n    or candidate->>'source_pin' is distinct from s.source_pin or candidate->>'catalog_hash' is distinct from s.catalog_hash\n    or candidate->'proof_refs' is distinct from proof_refs or candidate->'roleplay_policy' is distinct from s.roleplay_policy\n    or candidate->'independent_audit_proven' is distinct from 'false'::jsonb or candidate->'standard_claim_expiry_enforced' is distinct from 'false'::jsonb\n    or candidate->>'authority_epoch' is distinct from p.authority_epoch::text or admitted_manifest_hash !~ '^[0-9a-f]{64}$'\n    or manifest->>'id' is distinct from r.manifest_id::text or manifest#>'{safe,owners}' is distinct from s.safe_owners\n    or manifest#>>'{safe,address}' is distinct from s.safe_address or manifest#>>'{safe,threshold}' is distinct from s.safe_threshold::text\n    or candidate#>>'{observed,providers,0,url}' is distinct from 'https://polygon-amoy.drpc.org'\n    or candidate#>>'{observed,providers,1,url}' is distinct from 'https://polygon-amoy-bor-rpc.publicnode.com'\n    or jsonb_array_length(candidate#>'{observed,providers}')<>2\n    or expiry<=clock_timestamp() or (candidate#>>'{observed,block,timestamp}')::timestamptz>clock_timestamp()+interval '30 seconds'\n    or (candidate#>>'{observed,block,timestamp}')::timestamptz<clock_timestamp()-interval '20 minutes' then\n    raise exception 'fund_admission_exact_evidence_required' using errcode='23514';end if;\n  if manifest#>>'{token_details,name}' is distinct from r.input->>'token_name' or manifest#>>'{token_details,symbol}' is distinct from r.input->>'token_symbol'\n    or manifest#>>'{token_details,decimals}' is distinct from r.input->>'security_unit_decimals'\n    or manifest->'token_details'->'claim_topics' is distinct from r.input->'claim_topics'\n    or candidate->>'class_id' is distinct from r.input->>'class_id' or candidate->>'class_name' is distinct from r.input->>'class_name'\n    or manifest->>'product_binding_hash' is distinct from r.input->>'product_binding_hash'\n    or candidate#>>'{deployment_expectation,deployment,salt}' is distinct from r.input->>'deployment_salt'\n    or candidate#>'{deployment_expectation,manifest}' is distinct from manifest or candidate#>'{issuance_expectation,manifest}' is distinct from manifest then\n    raise exception 'fund_admission_current_terms_required' using errcode='23514';end if;\n  perform bx1_private.fund_roleplay_enter(r.operating_context,r.product_id,'admit_fund_release',r.request_key);\n  foreach receipt_kind in array array['CONFORMANCE','GOVERNANCE','OBSERVATION_POLICY','ROLE_STATE'] loop\n    receipt_id:=(proof_refs->>case receipt_kind when 'CONFORMANCE' then 'conformance_receipt_id' when 'GOVERNANCE' then 'governance_receipt_id'\n      when 'OBSERVATION_POLICY' then 'observation_policy_receipt_id' else 'role_state_receipt_id' end)::uuid;\n    evidence:=jsonb_build_object('kind',receipt_kind,'setup_id',s.id,'setup_revision',s.revision,'product_id',r.product_id,'offering_revision_id',r.offering_revision_id,\n      'terms_hash',s.terms_hash,'configuration_hash',s.configuration_hash,'catalog_hash',s.catalog_hash,'source_pin',s.source_pin,\n      'roleplay_policy_id',p.id,'authority_epoch',p.authority_epoch,'independence_proven',false,'audit_proven',false,'expiry_enforced_on_chain',false,\n      'conformance_receipt_id',r.conformance_receipt_id,'observed',candidate->'observed','safe',manifest->'safe','candidate_hash',bx1_portal.fund_digest(candidate));\n    insert into bx1_portal.fund_admission_receipts(id,request_id,kind,evidence,evidence_hash) values(receipt_id,r.id,receipt_kind,evidence,bx1_portal.fund_digest(evidence));\n  end loop;\n  manifest:=manifest||jsonb_build_object('status','ADMITTED','hash',admitted_manifest_hash);\n  insert into bx1_portal.fund_release_manifests(id,product_id,offering_revision_id,native_organisation_id,environment,chain_id,release_version,source_commit,\n    manifest_hash,configuration_hash,product_binding_hash,terms_hash,authority_epoch,expected_token_address,controller_address,execution_account,required_confirmations,\n    security_unit_decimals,class_id,class_name,deployment_expectation,issuance_expectation,status,conformance_receipt_id,governance_receipt_id,observation_policy_receipt_id,admitted_by,admitted_until)\n    values(r.manifest_id,r.product_id,r.offering_revision_id,p.native_organisation_id,'TESTNET',80002,'ERC3643_4.1.3',s.source_pin,admitted_manifest_hash,\n      s.configuration_hash,r.input->>'product_binding_hash',s.terms_hash,p.authority_epoch,manifest#>>'{suite,token,address}',manifest#>>'{controller,address}',s.safe_address,\n      (r.input->>'required_confirmations')::integer,(r.input->>'security_unit_decimals')::integer,(r.input->>'class_id')::uuid,r.input->>'class_name',\n      jsonb_set(candidate->'deployment_expectation','{manifest}',manifest),jsonb_set(candidate->'issuance_expectation